Optimal Solution (Linear Scan in O(N) Time, O(1) Auxiliary Space):

```python
def operations_binary_string(s: str) -> int:
    if not s:
        return -1
    res = int(s[0])
    i = 1
    while i < len(s):
        op = s[i]
        val = int(s[i + 1])
        if op == 'A':
            res = res & val
        elif op == 'B':
            res = res | val
        elif op == 'C':
            res = res ^ val
        i += 2
    return res
```

```cpp
int operationsBinaryString(const string& str) {
    if (str.empty()) return -1;
    int res = str[0] - '0';
    for (size_t i = 1; i + 1 < str.length(); i += 2) {
        char op = str[i];
        int val = str[i + 1] - '0';
        if (op == 'A') res &= val;
        else if (op == 'B') res |= val;
        else if (op == 'C') res ^= val;
    }
    return res;
}
```
Complexity: O(N) Time, O(1) Space.

Optimal Solution (Single Pass or Two Pointer O(N) Time, O(N) Space):

```python
def move_hyphens(s: str) -> str:
    if s is None:
        return None
    hyphens = s.count('-')
    chars = [c for c in s if c != '-']
    return ('-' * hyphens) + ''.join(chars)
```

```cpp
string moveHyphens(string s) {
    int hyphenCount = 0;
    string chars = "";
    for (char c : s) {
        if (c == '-') hyphenCount++;
        else chars += c;
    }
    return string(hyphenCount, '-') + chars;
}
```
Complexity: O(N) Time, O(N) Space (In-place C++ string shift is also possible with O(1) extra memory).

Mathematical Solution (O(1) Time and O(1) Space via Arithmetic Progressions):

```python
def difference_of_sums(n: int, m: int) -> int:
    total_sum = m * (m + 1) // 2
    k = m // n  # count of numbers divisible by n
    sum2 = n * (k * (k + 1) // 2)
    sum1 = total_sum - sum2
    return sum1 - sum2
```

```cpp
int differenceOfSums(int n, int m) {
    long long total_sum = 1LL * m * (m + 1) / 2;
    int k = m / n;
    long long sum2 = 1LL * n * (1LL * k * (k + 1) / 2);
    long long sum1 = total_sum - sum2;
    return (int)(sum1 - sum2);
}
```
Complexity: Closed-form O(1) Time and O(1) Space. (Linear simulation in O(M) time is also accepted during drives).

Optimal Solution (Linear Scan in O(N) Time, O(1) Space):

```python
def rat_count_house(r: int, unit: int, arr: list[int]) -> int:
    if not arr:
        return 0
    total_needed = r * unit
    accumulated = 0
    for idx, food in enumerate(arr):
        accumulated += food
        if accumulated >= total_needed:
            return idx + 1
    return -1
```

```cpp
int ratCountHouse(int r, int unit, const vector<int>& arr) {
    if (arr.empty()) return 0;
    int needed = r * unit;
    int current = 0;
    for (int i = 0; i < (int)arr.size(); i++) {
        current += arr[i];
        if (current >= needed) return i + 1;
    }
    return -1;
}
```
Complexity: O(N) Time, O(1) Space.

Optimal Solution (Single Pass Tracking Two Minima in O(N) Time, O(1) Space):

```python
def product_smallest_pair(sum_val: int, arr: list[int]) -> int:
    if len(arr) < 2:
        return -1
    first_min = float('inf')
    second_min = float('inf')
    for x in arr:
        if x < first_min:
            second_min = first_min
            first_min = x
        elif x < second_min:
            second_min = x
    if first_min + second_min < sum_val:
        return first_min * second_min
    return 0
```

```cpp
int productSmallestPair(int sumVal, const vector<int>& arr) {
    if (arr.size() < 2) return -1;
    int firstMin = INT_MAX, secondMin = INT_MAX;
    for (int x : arr) {
        if (x < firstMin) {
            secondMin = firstMin;
            firstMin = x;
        } else if (x < secondMin) {
            secondMin = x;
        }
    }
    if (firstMin + secondMin < sumVal) return firstMin * secondMin;
    return 0;
}
```
Complexity: O(N) Time, O(1) Space.

Optimal Solution (Single Pass Boolean Checks in O(N) Time, O(1) Space):

```python
def check_password(s: str) -> int:
    if not s or len(s) < 4:
        return 0
    if s[0].isdigit():
        return 0
    has_digit = False
    has_upper = False
    for ch in s:
        if ch == ' ' or ch == '/':
            return 0
        if ch.isdigit():
            has_digit = True
        elif ch.isupper():
            has_upper = True
    return 1 if (has_digit and has_upper) else 0
```

```cpp
int checkPassword(const string& str) {
    if (str.length() < 4 || isdigit(str[0])) return 0;
    bool hasDigit = false, hasCap = false;
    for (char c : str) {
        if (c == ' ' || c == '/') return 0;
        if (isdigit(c)) hasDigit = true;
        else if (isupper(c)) hasCap = true;
    }
    return (hasDigit && hasCap) ? 1 : 0;
}
```
Complexity: O(N) Time, O(1) Space.

Optimal Solution (O(N) Selection or O(N log N) Sorting):

```python
def large_small_sum(arr: list[int]) -> int:
    if len(arr) <= 3:
        return 0
    evens = [arr[i] for i in range(0, len(arr), 2)]
    odds = [arr[i] for i in range(1, len(arr), 2)]
    if len(evens) < 2 or len(odds) < 2:
        return 0
    evens.sort()
    odds.sort()
    second_largest_even = evens[-2]
    second_smallest_odd = odds[1]
    return second_largest_even + second_smallest_odd
```

```cpp
int largeSmallSum(const vector<int>& arr) {
    if (arr.size() <= 3) return 0;
    vector<int> evens, odds;
    for (size_t i = 0; i < arr.size(); i++) {
        if (i % 2 == 0) evens.push_back(arr[i]);
        else odds.push_back(arr[i]);
    }
    sort(evens.begin(), evens.end());
    sort(odds.begin(), odds.end());
    return evens[evens.size() - 2] + odds[1];
}
```
Complexity: O(N log N) Time with sorting, O(N) Space. (Can be optimized to O(N) Time, O(1) Space using two-min / two-max tracking).

Optimal Solution (Linear Pass in O(N) Time, O(N) or In-Place Space):

```python
def replace_chars(s: str, ch1: str, ch2: str) -> str:
    if not s or ch1 == ch2:
        return s
    res = []
    for c in s:
        if c == ch1:
            res.append(ch2)
        elif c == ch2:
            res.append(ch1)
        else:
            res.append(c)
    return ''.join(res)
```

```cpp
string replaceChar(string str, char ch1, char ch2) {
    for (char &c : str) {
        if (c == ch1) c = ch2;
        else if (c == ch2) c = ch1;
    }
    return str;
}
```
Complexity: O(N) Time, O(1) Auxiliary Space for in-place string modification.

Optimal Solution (Modulo 10^k in O(log N) Time, O(1) Space):

```python
def is_automorphic(n: int) -> int:
    if n < 0:
        return 0
    sq = n * n
    temp = n
    mod = 1
    while temp > 0:
        mod *= 10
        temp //= 10
    return 1 if (sq % mod == n) else 0
```

```cpp
int isAutomorphic(int n) {
    if (n < 0) return 0;
    long long sq = 1LL * n * n;
    long long mod = 1;
    int temp = n;
    while (temp > 0) {
        mod *= 10;
        temp /= 10;
    }
    return (sq % mod == n) ? 1 : 0;
}
```
Complexity: O(log10 N) Time (number of digits in N), O(1) Space.
